const content=document.querySelector('#set-content'),crumbs=document.querySelector('.breadcrumbs');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const prefabMode=location.pathname.startsWith('/scene-generator/prefabs'),base=prefabMode?'/scene-generator/prefabs':'/sets',section=prefabMode?'Prefabs':'Sets';
if(prefabMode)document.body.classList.add('prefab-browser');
const href=s=>base+'/'+s.slug;
function tile(s){return `<a class="set-card" href="${href(s)}"><img src="${s.preview}" alt="${esc(s.title)} diorama" loading="lazy"><div class="copy"><span class="set-id">${s.id}</span><h2>${esc(s.title)}</h2><p>${esc(s.intent)}</p></div></a>`;}
async function start(){
 const r=await fetch('/sets-data/catalog.json');if(!r.ok)throw Error('Sets could not load.');const catalog=await r.json();
 const slug=location.pathname.slice(base.length).replace(/^\//,'').replace(/\/$/,'');
 const set=catalog.sets.find(s=>s.slug===slug);
 if(!slug||slug==='.html'){
 document.title=section+' · Abbie’s Ranch';crumbs.innerHTML=prefabMode?'<a href="/scene-generator">Scene Generator</a><span>/</span><span>Prefabs</span>':'<a href="/">Abbie’s Ranch</a><span>/</span><span>Sets</span>';
 content.innerHTML='<div class="title-row"><h1>'+section+'</h1><span class="set-id">ABBIE’S RANCH</span></div>'+(prefabMode?'<input class="prefab-search" type="search" aria-label="Find a prefab" placeholder="Name, slug or ID"><div id="prefab-results"></div>':'')+'<div class="set-grid">'+catalog.sets.filter(s=>!s.parent).map(tile).join('')+'</div>'+(prefabMode?'<details class="pieces prefab-pieces"><summary>All pieces & scenes <small>'+catalog.sets.filter(s=>s.parent).length+'</small></summary><div class="prefab-list">'+catalog.sets.filter(s=>s.parent).map(s=>`<a href="${href(s)}"><code>${esc(s.id)}</code><span>${esc(s.title)}</span></a>`).join('')+'</div></details>':'');
 if(prefabMode)document.querySelector('.prefab-search').oninput=e=>{const q=e.target.value.trim().toLowerCase();document.querySelector('.set-grid').hidden=!!q;document.querySelector('.prefab-pieces').hidden=!!q;const found=catalog.sets.filter(s=>(s.id+' '+s.slug+' '+s.title).toLowerCase().includes(q));document.querySelector('#prefab-results').innerHTML=q?'<div class="prefab-list">'+(found.length?found.map(s=>`<a href="${href(s)}"><code>${esc(s.id)}</code><span>${esc(s.title)}</span></a>`).join(''):'<p>No matching prefabs.</p>')+'</div>':'';};return;}

 if(!set){content.innerHTML='<h1>Set not found</h1><p><a href="/sets">Back to Sets</a></p>';return;}
 document.title=set.title+' · '+section+' · Abbie’s Ranch';
 const ancestors=[];let parent=set.parent;while(parent){const item=catalog.sets.find(s=>s.slug===parent);if(!item||ancestors.includes(item))break;ancestors.unshift(item);parent=item.parent;}
 crumbs.innerHTML=(prefabMode?'<a href="/scene-generator">Scene Generator</a>':'<a href="/">Abbie’s Ranch</a>')+'<span>/</span><a href="'+base+'">'+section+'</a><span>/</span>'+ancestors.map(s=>`<a href="${href(s)}">${esc(s.title)}</a><span>/</span>`).join('')+`<span aria-current="page">${esc(set.title)}</span>`;
 const children=catalog.sets.filter(s=>s.parent===set.slug&&s.kind!=='asset'),families=[...new Set(set.pieces.map(p=>p.family))];
 content.innerHTML=`<div class="title-row"><div><h1>${esc(set.title)}</h1><p class="intent">${esc(set.intent)}</p></div><span class="set-id">${set.id}</span></div><div class="scene-frame"><div id="scene"></div>${set.preview?`<img class="poster" src="${set.preview}" alt="${esc(set.title)} diorama">`:""}<div class="scene-note"><small></small><p></p></div><span id="scene-status" role="status">Opening 3D…</span><div class="set-tools"><button id="home-view" aria-label="Reset scene view">Reset view</button><button id="turn-view" aria-label="Turn scene">↻</button><button id="zoom-view" aria-label="Zoom closer">＋</button><button id="tree-view" hidden>Tree</button><button id="barn-view" hidden>Barn</button></div></div>${set.views?.length?'<div class="encounter-views" aria-label="Explore this set">'+set.views.map((v,i)=>`<button data-view="${i}" disabled>${esc(v.label)}</button>`).join('')+'</div><p class="encounter-note" aria-live="polite">Choose a stop, or explore freely.</p>':''}<details class="pieces" ${set.pieces.length<=8&&!set.views?.length?'open':''}><summary>Pieces <small>${set.pieces.length}</small></summary>${set.pieces.length>8?'<div class="piece-tools"><input id="piece-search" type="search" aria-label="Find a piece" placeholder="ID or intent"><select id="piece-family" aria-label="Piece family"><option value="">All pieces</option>'+families.map(f=>`<option>${esc(f)}</option>`).join('')+'</select></div>':''}<div class="piece-list"></div></details>${children.length?'<details class="children"><summary>Scenes <small>'+children.length+'</small></summary><div class="child-grid">'+children.map(tile).join('')+'</div></details>':''}<div class="set-links">${set.model?`<a href="${set.model}" download>3D file</a>`:'<a href="/3d">Ranch study</a>'}${set.metadata?`<a href="${set.metadata}">Set details</a>`:'<a href="/sets-data/catalog.json">Set index</a>'}</div>`;
 function draw(){const term=document.querySelector('#piece-search')?.value.toLowerCase().trim()||'',family=document.querySelector('#piece-family')?.value||'';const list=set.pieces.filter(p=>(!family||p.family===family)&&(!term||(p.id+' '+p.intent).toLowerCase().includes(term)));document.querySelector('.piece-list').innerHTML=list.length?list.map(p=>`<div class="piece"><code>${catalog.sets.some(s=>s.id===p.id)?`<a href="${href(catalog.sets.find(s=>s.id===p.id))}">${p.id}</a>`:p.id}</code><span>${esc(p.intent)}</span></div>`).join(''):'<p class="empty">No matching pieces.</p>';}
 if(set.kind==='asset')document.querySelector('.pieces').hidden=true;
 document.querySelector('#piece-search')?.addEventListener('input',draw);document.querySelector('#piece-family')?.addEventListener('change',draw);draw();
 const ready=()=>{document.querySelector('.scene-frame').classList.add('ready');document.querySelector('#scene-status').textContent='Drag to orbit · pinch to zoom';};
 try{if(set.viewer==='ranch'){window.addEventListener('set-scene-ready',ready,{once:true});await import('/sets-ranch-scene.js');}else{const {showModel}=await import('/sets-viewer.js');const viewer=await showModel(set.model,set);ready();document.querySelectorAll('[data-view]').forEach(button=>{button.disabled=false;button.onclick=()=>{const v=set.views[Number(button.dataset.view)];viewer.focus(v);document.querySelector('.encounter-note').textContent=v.intent;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));};});if(set.views?.length){document.querySelector('#home-view').onclick=()=>{viewer.home();document.querySelector('.encounter-note').textContent='Choose a stop, or explore freely.';document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed','false'));};}}}
 catch(e){document.querySelector('#scene-status').textContent='Preview shown · 3D unavailable';console.error(e);}
}
start().catch(e=>{content.innerHTML='<h1>Sets</h1><p>'+esc(e.message)+'</p>';});
